function normalizeExcelHeader(h,idx){
  let s=String(h||"").trim();
  // Normalizar variantes conocidas de headers del Excel ROP02
  if(s==="Fecha:")s="Fecha";
  if(s==="Cant.Hs/ KM"||s==="Cant.Hs")s="Cant. Hs.";
  if(s==="Proyecto ")s="Proyecto";
  return s||`col_${idx}`;
}
function cellStr(arr,idx){return String(arr?.[idx]??"").trim();}
function looksLikeROP05IdPrefixedRow(arr){
  // Soporta exportaciones de AppSheet/base normalizada:
  // A = ID_Carga, B = FechaCarga, C = CorreoSupervisor, ...
  // y también la plantilla histórica sin ID_Carga: A = FechaCarga.
  const c0=cellStr(arr,0);
  const c1=cellStr(arr,1);
  const c2=cellStr(arr,2);
  if(cleanKey(c0)==="id_carga")return true;
  if((normDate(c1)||/^\d{4}-\d{2}-\d{2}/.test(c1)||/^\d{1,2}\/\d{1,2}\/\d{4}/.test(c1)) && String(c2||"").includes("@"))return true;
  return false;
}
function buildROP05ImportObjectByPosition(arr){
  const offset=looksLikeROP05IdPrefixedRow(arr)?1:0;
  const fechaCarga=cellStr(arr,offset+0);
  const supervisor=cellStr(arr,offset+1);
  const proyecto=cellStr(arr,offset+2);
  const grupo=cellStr(arr,offset+3);
  const equipo=cellStr(arr,offset+4);
  const parte=cellStr(arr,offset+5);
  const tipoEquipo=cellStr(arr,offset+6);
  const fechaParte=cellStr(arr,offset+7);
  const tarea=cellStr(arr,offset+8);
  const horas=cellStr(arr,offset+9);
  const cantidad=cellStr(arr,offset+10);
  const unidad=cellStr(arr,offset+11);
  const obs=cellStr(arr,offset+12);

  // Importante: se cargan alias viejos y nuevos.
  // Así el frontend analiza por columna y Apps Script puede escribir tanto
  // en planillas con encabezados viejos como con encabezados nuevos.
  return {
    FechaCarga:fechaCarga,
    "Marca Tmeporal":fechaCarga,
    "Marca Temporal":fechaCarga,
    CorreoSupervisor:supervisor,
    Supervisor:supervisor,
    Proyecto:proyecto,
    GrupoTrabajo:grupo,
    "Grupo de trabajo":grupo,
    Equipo:equipo,
    "Codigo Int":equipo,
    "Código Int":equipo,
    NroParte:parte,
    "N° de Parte":parte,
    "Nº de Parte":parte,
    "N de Parte":parte,
    TipoEquipo:tipoEquipo,
    "Tipo Equipo":tipoEquipo,
    "Tipo de máquina":tipoEquipo,
    "Tipo de maquina":tipoEquipo,
    FechaParte:fechaParte,
    "Fecha del Parte Diario":fechaParte,
    Tarea:tarea,
    HorasProductivas:horas,
    "CANTIDAD DE HS PRODUCTIVAS EFECTIVAS\n(SOLO CANTIDAD)":horas,
    "CANTIDAD DE HS PRODUCTIVAS EFECTIVAS (SOLO CANTIDAD)":horas,
    "HS PRODUCTIVAS EFECTIVAS":horas,
    CantidadProduccion:cantidad,
    "CANTIDAD DE PRODUCCIÓN DE LA TAREA REALIZADA\n(SIN UNIDADES DE MEDIDA)":cantidad,
    "CANTIDAD DE PRODUCCION DE LA TAREA REALIZADA (SIN UNIDADES DE MEDIDA)":cantidad,
    "CANTIDAD DE PRODUCCIÓN":cantidad,
    "CANTIDAD DE PRODUCCION":cantidad,
    Unidad:unidad,
    "UNIDAD DE PRODUCTIVIDAD":unidad,
    Observacion:obs,
    Observación:obs,
    "OBSERVACION DE LA TAREA SEGUN LA SELECCIONADA\n-Tipo de suelo (duro,blando)\n-Dimensiones\n-Nombre de lugar de trabajo\n-Etc.":obs,
    "OBSERVACION DE LA TAREA SEGUN LA SELECCIONADA":obs,
    "OBSERVACION DE LA TAREA":obs,
    "OBSERVACIONES":obs,
    Mes:cellStr(arr,13),
  };
}
function countValidROP05ImportRows(rows){
  return normalizeROP05(rows||[]).length;
}
function pickBestSheetForTarget(wb,target,headerIdx){
  // Para ROP05 NO confiar en la primera hoja. Los archivos pueden traer hojas auxiliares
  // como Codigos/Equipos/Inicio. Elegimos la hoja con más filas ROP05 válidas.
  if(target?.kind!=="rop05")return wb.SheetNames[0];
  let bestName=wb.SheetNames[0];
  let bestCount=-1;
  wb.SheetNames.forEach(name=>{
    const ws=wb.Sheets[name];
    if(!ws)return;
    const matrix=XLSX.utils.sheet_to_json(ws,{header:1,defval:"",raw:false,dateNF:"yyyy-mm-dd"});
    const rows=[];
    for(let i=headerIdx+1;i<matrix.length;i++){
      const arr=matrix[i]||[];
      if(arr.every(v=>String(v||"").trim()===""))continue;
      rows.push(buildROP05ImportObjectByPosition(arr));
    }
    const valid=countValidROP05ImportRows(rows);
    if(valid>bestCount){bestCount=valid;bestName=name;}
  });
  return bestName;
}
function readExcelAsObjects(file,targetOrHeaderRow){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=()=>reject(new Error("No se pudo leer el archivo Excel."));
    reader.onload=e=>{
      try{
        const data=new Uint8Array(e.target.result);
        const wb=XLSX.read(data,{type:"array",cellDates:true});
        if(!wb.SheetNames?.length)throw new Error("El Excel no contiene hojas.");
        const target=typeof targetOrHeaderRow==="object"?targetOrHeaderRow:null;
        const headerRow=target?.headerRow??targetOrHeaderRow;
        const headerIdx=Math.max(0,(headerRow||1)-1);
        const selectedSheetName=pickBestSheetForTarget(wb,target,headerIdx);
        const ws=wb.Sheets[selectedSheetName];
        if(!ws)throw new Error("El Excel no contiene la hoja seleccionada.");
        const matrix=XLSX.utils.sheet_to_json(ws,{header:1,defval:"",raw:false,dateNF:"yyyy-mm-dd"});

        // ROP05: leer SIEMPRE por posición e ignorar encabezados.
        // A:M = formato histórico. Si existe ID_Carga en A, usa B:N automáticamente.
        if(target?.kind==="rop05"){
          const rows=[];
          for(let i=headerIdx+1;i<matrix.length;i++){
            const arr=matrix[i]||[];
            if(arr.every(v=>String(v||"").trim()===""))continue;
            rows.push(buildROP05ImportObjectByPosition(arr));
          }
          return resolve({
            sheetName:selectedSheetName,
            headers:["FechaCarga","CorreoSupervisor","Proyecto","GrupoTrabajo","Equipo","NroParte","TipoEquipo","FechaParte","Tarea","HorasProductivas","CantidadProduccion","Unidad","Observacion"],
            rows
          });
        }

        // ROP02: leer SIEMPRE por posición fija según la estructura actual:
        // A Fecha · B Interno · C Equipo · D Operador · E Supervisor Delta · F Supervisor Cliente
        // G Turno · H N° Parte · I Proyecto · J HI · K HF · L Cant. Hs. · M Combustible
        // N Aceite · O Trabajo · P Desgaste · Q Observaciones.
        // Esto evita corrimientos cuando se agregó la columna C "Equipo" al lado de "Interno".
        if(target?.kind==="rop02"){
          const rows=[];
          for(let i=headerIdx+1;i<matrix.length;i++){
            const arr=matrix[i]||[];
            if(arr.every(v=>String(v||"").trim()===""))continue;
            rows.push(buildROP02ImportObjectByPosition(arr,target.proyecto));
          }
          return resolve({
            sheetName:selectedSheetName,
            headers:["Fecha","Interno","Equipo","Operador","Supervisor Delta","Supervisor Vial Cliente","Turno de trabajo","N° Parte","Proyecto","Horómetro inicial","Horómetro final","Cant. Hs.","Combustible","Aceite","Descripción de los trabajos realizados","Información sobre Desgaste","Observaciones"],
            rows
          });
        }

        const header=(matrix[headerIdx]||[]).map(normalizeExcelHeader);
        const rows=[];
        for(let i=headerIdx+1;i<matrix.length;i++){
          const arr=matrix[i]||[];
          if(arr.every(v=>String(v||"").trim()===""))continue;
          const obj={};
          header.forEach((h,j)=>{obj[h]=String(arr[j]??"").trim();});
          rows.push(obj);
        }
        resolve({sheetName:selectedSheetName,headers:header,rows});
      }catch(err){reject(err);}
    };
    reader.readAsArrayBuffer(file);
  });
}

function parsePastedTable(text){
  return String(text||"")
    .replace(/\r\n/g,"\n")
    .replace(/\r/g,"\n")
    .split("\n")
    .map(line=>line.split("\t").map(cell=>String(cell||"").trim()))
    .filter(row=>row.some(cell=>cell!==""));
}
function rowLooksLikeHeaderROP05(row){
  const joined=(row||[]).join(" ").toLowerCase();
  return joined.includes("fechacarga")||joined.includes("marca temporal")||joined.includes("marca tmeporal")||joined.includes("correosupervisor")||joined.includes("codigo int")||joined.includes("fecha del parte")||joined.includes("horasproductivas");
}
function buildROP05RowsFromPastedText(text){
  const matrix=parsePastedTable(text);
  const data=matrix.filter((row,idx)=>!(idx===0&&rowLooksLikeHeaderROP05(row)));
  return data.map(buildROP05ImportObjectByPosition).filter(r=>{
    const fechaParte=String(r.FechaParte||r["Fecha del Parte Diario"]||"").trim();
    const equipo=String(r.Equipo||r["Codigo Int"]||"").trim();
    const tarea=String(r.Tarea||"").trim();
    return fechaParte||equipo||tarea;
  });
}


function rowLooksLikeGenericHeader(row){
  const cells=(row||[]).map(c=>cleanKey(c));
  const c0=cells[0]||"";
  const c1=cells[1]||"";
  const c2=cells[2]||"";
  const c3=cells[3]||"";
  const c4=cells[4]||"";
  const c5=cells[5]||"";
  const c6=cells[6]||"";

  // No mirar toda la fila: en ROP02 una fila válida puede traer textos como
  // "Equipo Operativo..." y antes se confundía con encabezado, descartando
  // la primera fila pegada (por ejemplo CAA-0002-JM).
  const firstCells=[c0,c1,c2,c3,c4,c5,c6].join(" ");

  const looksROP02Header =
    (c0==="fecha"||c0==="fecha:"||c0.includes("fecha")) &&
    (c1==="interno"||c1.includes("interno")) &&
    (
      ((c2==="equipo"||c2.includes("equipo")) && (c3.includes("operador")||c3.includes("operario")) && c4.includes("supervisor")) ||
      ((c2.includes("operador")||c2.includes("operario")) && c3.includes("supervisor"))
    );

  const looksROP05Header =
    (c0.includes("fechacarga")||c0.includes("fecha carga")||c0.includes("marca temporal")) &&
    (firstCells.includes("supervisor")||firstCells.includes("codigo")||firstCells.includes("equipo"));

  const looksRMA15Header =
    c0.includes("fecha") &&
    (firstCells.includes("turno")||firstCells.includes("tipo mantenimiento")||firstCells.includes("codigo interno"));

  const looksInsumosHeader =
    (c0.includes("codigo")||c0.includes("código")) &&
    (c1.includes("descripcion")||c1.includes("descripción")||c1.includes("articulo")||c1.includes("artículo"));

  return looksROP02Header||looksROP05Header||looksRMA15Header||looksInsumosHeader;
}
function buildROP02ImportObjectByPosition(arr,proyectoDefault){
  const fecha=cellStr(arr,0);
  const interno=cellStr(arr,1);
  const equipo=cellStr(arr,2);
  const operador=cellStr(arr,3);
  const supervisorDelta=cellStr(arr,4);
  const supervisorCliente=cellStr(arr,5);
  const turno=cellStr(arr,6);
  const parte=cellStr(arr,7);
  const proyecto=cellStr(arr,8)||proyectoDefault||"";
  const hi=cellStr(arr,9);
  const hf=cellStr(arr,10);
  const hs=cellStr(arr,11);
  const combustible=cellStr(arr,12);
  const aceite=cellStr(arr,13);
  const descripcion=cellStr(arr,14);
  const desgaste=cellStr(arr,15);
  const observaciones=cellStr(arr,16);
  return {
    Fecha:fecha,Interno:interno,Equipo:equipo,Operador:operador,"Supervisor Delta":supervisorDelta,"Supervisor Vial Cliente":supervisorCliente,
    "Turno de trabajo":turno,"N° Parte":parte,Proyecto:proyecto,"Horómetro inicial":hi,"Horómetro final":hf,"Cant. Hs.":hs,
    Combustible:combustible,Aceite:aceite,"Descripción de los trabajos realizados":descripcion,"Información sobre Desgaste":desgaste,Observaciones:observaciones
  };
}
function looksLikeRMA15IdPrefixedRow(arr){
  // Soporta pegar desde la planilla RMA15 cuando la columna A es ID/RowKey
  // y los datos reales empiezan en la columna B.
  // A puede ser número (1381) o un ID hex de 8 caracteres.
  const c0=cellStr(arr,0);
  const c1=cellStr(arr,1);
  const c2=cellStr(arr,2);
  const c3=cellStr(arr,3);
  const c0IsId=/^\d+$/.test(c0)||/^[a-f0-9]{8}$/i.test(c0)||cleanKey(c0)==="id"||cleanKey(c0)==="id ot"||cleanKey(c0)==="id_ot";
  const c1IsDate=!!normDate(c1)||/^\d{1,2}\/\d{1,2}\/\d{4}/.test(c1)||/^\d{4}-\d{2}-\d{2}/.test(c1);
  const c2LooksTurno=/^(dia|día|noche|td|tn)$/i.test(String(c2||"").trim());
  const c3LooksProyecto=cleanKey(c3).includes("jose")||cleanKey(c3).includes("filo")||cleanKey(c3).includes("vicu");
  return c0IsId&&c1IsDate&&(c2LooksTurno||c3LooksProyecto);
}
function looksLikeRMA15OldOrder(arr,offset=0){
  // Formato anterior: Fecha · Código interno · Equipo · Turno · Tipo mant. ...
  const c1=cellStr(arr,offset+1);
  const c3=cellStr(arr,offset+3);
  const c1LooksMachine=/^[A-Z]{2,4}-?\d{2,5}(?:-JM)?$/i.test(c1)||/^(PREDIO|DELTA|TALLER)/i.test(c1);
  const c3LooksTurno=/^(dia|día|noche|td|tn)$/i.test(String(c3||"").trim());
  return c1LooksMachine&&c3LooksTurno;
}
function buildRMA15ImportObjectByPosition(arr,proyectoDefault){
  // Formatos aceptados:
  // 1) A Fecha OT · B Turno · C Proyecto · D Tipo mant. · E Equipo · F Código interno ...
  // 2) A ID/RowKey · B Fecha OT · C Turno · D Proyecto · E Tipo mant. · F Equipo · G Código interno ...
  // 3) Formato anterior: Fecha · Código interno · Equipo · Turno · Tipo mant. ...
  // Si existe ID/RowKey en A, se ignora y se empieza a leer desde la fecha.
  const offset=looksLikeRMA15IdPrefixedRow(arr)?1:0;
  const oldOrder=looksLikeRMA15OldOrder(arr,offset);

  // FIX PROYECTO RMA15:
  // La hoja RMA15 no tiene encabezado "Proyecto"; la columna C se llama
  // "LUGAR DONDE ESTAN LOS EQUIPOS". Por eso, además de "Proyecto"
  // mandamos el valor con el nombre real de la columna para que upsert_sparse
  // complete esa celda. Funciona igual para JM y Filo del Sol porque toma
  // target.proyecto según el botón usado.
  const proyectoPegado=oldOrder?"":cellStr(arr,offset+2);
  const proyectoFinal=proyectoDefault||proyectoPegado||"";

  const obj=oldOrder?{
    "Fecha de OT":cellStr(arr,offset+0),
    "TURNO EN QUE SE HIZO LA OT":cellStr(arr,offset+3),
    Proyecto:proyectoFinal,
    "LUGAR DONDE ESTAN LOS EQUIPOS":proyectoFinal,
    "Lugar donde estan los equipos":proyectoFinal,
    "TIPO DE MANTENIMIENTO":cellStr(arr,offset+4),
    EQUIPO:cellStr(arr,offset+2),
    "CODIGO N° INTERNO":cellStr(arr,offset+1),
    "Km / hs":cellStr(arr,offset+5),
    "INTERVENCIÓN O REPARACIÓN REALIZADA (Si es PM, especificar cual) LOS SOPLETEOS DE FILTROS VAN EN ESTA SECCION O CUALQUIER SERVICIO QUE SE REALICE)":cellStr(arr,offset+6),
    "¿EQUIPO QUEDO OPERATIVO?":cellStr(arr,offset+7),
    OBSERVACIONES:cellStr(arr,offset+8),
    _proyectoForzado:proyectoFinal,
  }:{
    "Fecha de OT":cellStr(arr,offset+0),
    "TURNO EN QUE SE HIZO LA OT":cellStr(arr,offset+1),
    Proyecto:proyectoFinal,
    "LUGAR DONDE ESTAN LOS EQUIPOS":proyectoFinal,
    "Lugar donde estan los equipos":proyectoFinal,
    "TIPO DE MANTENIMIENTO":cellStr(arr,offset+3),
    EQUIPO:cellStr(arr,offset+4),
    "CODIGO N° INTERNO":cellStr(arr,offset+5),
    "Km / hs":cellStr(arr,offset+6),
    "INTERVENCIÓN O REPARACIÓN REALIZADA (Si es PM, especificar cual) LOS SOPLETEOS DE FILTROS VAN EN ESTA SECCION O CUALQUIER SERVICIO QUE SE REALICE)":cellStr(arr,offset+7),
    "¿EQUIPO QUEDO OPERATIVO?":cellStr(arr,offset+8),
    OBSERVACIONES:cellStr(arr,offset+9),
    _proyectoForzado:proyectoFinal,
  };
  // Desde la columna posterior a Observaciones: cantidad 1, codigo 1, nombre 1, cantidad 2, codigo 2, nombre 2...
  const insumosStart=offset+(oldOrder?9:10);
  for(let i=1;i<=10;i++){
    const base=insumosStart+(i-1)*3;
    obj[`cantidad ${i}`]=cellStr(arr,base);
    obj[`codigo ${i}`]=cellStr(arr,base+1);
    obj[`nombre ${i}`]=cellStr(arr,base+2);
  }
  return obj;
}
function buildInsumosImportObjectByPosition(arr){
  return {
    CODIGO:cellStr(arr,0),
    "DESCRIPCIÓN":cellStr(arr,1),
    "COSTO UNITARIO":cellStr(arr,2),
    Codigo:cellStr(arr,0),
    Descripcion:cellStr(arr,1),
    Precio:cellStr(arr,2),
  };
}
function buildRowsFromPastedTextForTarget(target,text){
  const matrix=parsePastedTable(text);
  const data=matrix.filter((row,idx)=>!(idx===0&&rowLooksLikeGenericHeader(row)));
  if(target.kind==="rop05")return data.map(buildROP05ImportObjectByPosition).filter(r=>String(r.FechaParte||r["Fecha del Parte Diario"]||r.Equipo||r["Codigo Int"]||r.Tarea||"").trim());
  if(target.kind==="rop02")return data.map(row=>buildROP02ImportObjectByPosition(row,target.proyecto)).filter(r=>String(r.Fecha||r.Interno||r["N° Parte"]||"").trim());
  if(target.kind==="rma15")return data.map(row=>buildRMA15ImportObjectByPosition(row,target.proyecto)).filter(r=>String(r["Fecha de OT"]||r["CODIGO N° INTERNO"]||r["TIPO DE MANTENIMIENTO"]||"").trim());
  if(target.kind==="insumos")return data.map(buildInsumosImportObjectByPosition).filter(r=>String(r.CODIGO||r["DESCRIPCIÓN"]||r["COSTO UNITARIO"]||"").trim());
  return [];
}
