function formatFileSize(bytes){
  const n=Number(bytes||0);
  if(n>=1024*1024)return `${(n/(1024*1024)).toFixed(1)} MB`;
  if(n>=1024)return `${(n/1024).toFixed(0)} KB`;
  return `${n} B`;
}
function ImportButton({target,fileEntry,preview,onFile,onRemove,onSelectPreview}){
  const inputRef=useRef(null);
  const hasFile=!!fileEntry;
  const hasPreview=!!preview;
  const changes=hasPreview?(preview.nuevos.length+preview.actualizados.length):0;
  const color=hasPreview?(changes>0?target.color:C.green):(hasFile?C.blue:target.color);
  return(
    <div style={{display:"flex",flexDirection:"column",gap:8,background:C.surface,border:`1px solid ${hasFile?color+"66":target.color+"44"}`,borderRadius:10,padding:12}}>
      <input ref={inputRef} type="file" accept=".xlsx,.xls,.xlsm,.csv" style={{display:"none"}} onChange={e=>{const file=e.target.files?.[0]; if(file)onFile(target,file); e.target.value="";}}/>
      <button onClick={()=>inputRef.current?.click()} style={{display:"flex",alignItems:"center",gap:10,justifyContent:"space-between",padding:"8px 4px",background:"transparent",border:"none",color:C.text,cursor:"pointer",fontFamily:"Inter",fontWeight:700,fontSize:13,textAlign:"left"}}>
        <span style={{display:"flex",alignItems:"center",gap:9}}><Icon name="parts" size={17} color={color}/>{target.label}</span>
        <span style={{fontSize:11,color}}>{hasFile?"Cambiar Excel":"Elegir Excel"}</span>
      </button>
      {hasFile?(
        <div style={{display:"flex",flexDirection:"column",gap:8}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}>
            <div style={{minWidth:0}}>
              <div style={{fontSize:11,color:C.text,fontWeight:700,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{fileEntry.fileName}</div>
              <div style={{fontSize:10,color:C.textMuted,marginTop:2}}>{hasPreview?preview.sheetName:`Cargado — ${formatFileSize(fileEntry.size)}`}</div>
            </div>
            <button onClick={()=>onRemove(target.id)} title="Quitar archivo" style={{flexShrink:0,width:22,height:22,borderRadius:"50%",border:`1px solid ${C.red}55`,background:C.redDim,color:C.red,cursor:"pointer",fontWeight:800}}>×</button>
          </div>
          {hasPreview?(
            <>
              <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:5}}>
                <div style={{background:C.greenDim,border:`1px solid ${C.green}33`,borderRadius:7,padding:"6px 7px"}}><div style={{fontSize:15,fontWeight:800,color:C.green}}>{preview.nuevos.length}</div><div style={{fontSize:9,color:C.textMuted}}>nuevas</div></div>
                <div style={{background:C.yellowDim,border:`1px solid ${C.yellow}33`,borderRadius:7,padding:"6px 7px"}}><div style={{fontSize:15,fontWeight:800,color:C.yellow}}>{preview.actualizados.length}</div><div style={{fontSize:9,color:C.textMuted}}>actualiz.</div></div>
                <div style={{background:C.blueDim,border:`1px solid ${C.blue}33`,borderRadius:7,padding:"6px 7px"}}><div style={{fontSize:15,fontWeight:800,color:C.blue}}>{preview.iguales.length}</div><div style={{fontSize:9,color:C.textMuted}}>iguales</div></div>
                <div style={{background:C.redDim,border:`1px solid ${C.red}33`,borderRadius:7,padding:"6px 7px"}}><div style={{fontSize:15,fontWeight:800,color:C.red}}>{preview.duplicados.length}</div><div style={{fontSize:9,color:C.textMuted}}>duplic.</div></div>
              </div>
              <button onClick={()=>onSelectPreview(preview)} style={{alignSelf:"flex-start",padding:"5px 9px",borderRadius:7,border:`1px solid ${target.color}44`,background:target.color+"18",color:target.color,cursor:"pointer",fontSize:11,fontWeight:700,fontFamily:"Inter"}}>Ver detalle</button>
            </>
          ):(
            <div style={{display:"flex",alignItems:"center",gap:7,padding:"7px 9px",borderRadius:7,background:C.blueDim,border:`1px solid ${C.blue}33`,color:C.blue,fontSize:11,fontWeight:700}}>
              <Icon name="check" size={12} color={C.blue}/> Archivo cargado, pendiente de analizar
            </div>
          )}
        </div>
      ):(
        <div style={{fontSize:11,color:C.textMuted,padding:"0 4px 4px"}}>Sin archivo cargado</div>
      )}
    </div>
  );
}
function ImportTargetLog({target,fileEntry,preview,result,onSelectPreview}){
  const hasFile=!!fileEntry;
  const hasPreview=!!preview;
  const cambios=hasPreview?preview.nuevos.length+preview.actualizados.length:0;
  const statusColor=result?C.green:(hasPreview?(cambios?C.yellow:C.green):(hasFile?C.blue:C.textMuted));
  const Line=({label,value,color=C.text})=>(
    <div style={{display:"flex",justifyContent:"space-between",gap:10,fontSize:11,lineHeight:1.35}}>
      <span style={{color:C.textMuted}}>{label}</span>
      <span style={{color,fontWeight:700,textAlign:"right",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",maxWidth:220}}>{value}</span>
    </div>
  );
  return(
    <div style={{height:"100%",minHeight:84,background:C.surface,border:`1px solid ${statusColor}44`,borderRadius:10,padding:12,display:"flex",flexDirection:"column",gap:8,justifyContent:"center"}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10}}>
        <div style={{display:"flex",alignItems:"center",gap:8,minWidth:0}}>
          <span style={{width:8,height:8,borderRadius:"50%",background:statusColor,boxShadow:`0 0 12px ${statusColor}66`,flexShrink:0}}/>
          <span style={{fontSize:12,fontWeight:800,color:C.text,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{target.sourceLabel}</span>
        </div>
        {hasPreview&&(
          <button onClick={()=>onSelectPreview(preview)} style={{padding:"4px 8px",borderRadius:7,border:`1px solid ${target.color}44`,background:target.color+"18",color:target.color,cursor:"pointer",fontSize:10,fontWeight:800,fontFamily:"Inter",flexShrink:0}}>Detalle</button>
        )}
      </div>

      {!hasFile&&(
        <div style={{fontSize:11,color:C.textMuted}}>Sin archivo cargado. El registro aparecerá acá cuando cargues y analices el Excel.</div>
      )}

      {hasFile&&!hasPreview&&(
        <>
          <Line label="Archivo" value={fileEntry.fileName}/>
          <Line label="Tamaño" value={formatFileSize(fileEntry.size)} color={C.blue}/>
          <Line label="Estado" value="Cargado en memoria, pendiente de análisis" color={C.blue}/>
        </>
      )}

      {hasPreview&&(
        <>
          <Line label="Hoja Excel" value={preview.sheetName||"—"}/>
          <Line label="Filas leídas" value={fmtNum(preview.total||0)} color={C.text}/>
          <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:6,marginTop:2}}>
            <div style={{background:C.greenDim,border:`1px solid ${C.green}33`,borderRadius:7,padding:"6px 7px"}}><div style={{fontSize:14,fontWeight:900,color:C.green}}>{preview.nuevos.length}</div><div style={{fontSize:9,color:C.textMuted}}>nuevas</div></div>
            <div style={{background:C.yellowDim,border:`1px solid ${C.yellow}33`,borderRadius:7,padding:"6px 7px"}}><div style={{fontSize:14,fontWeight:900,color:C.yellow}}>{preview.actualizados.length}</div><div style={{fontSize:9,color:C.textMuted}}>actualiz.</div></div>
            <div style={{background:C.blueDim,border:`1px solid ${C.blue}33`,borderRadius:7,padding:"6px 7px"}}><div style={{fontSize:14,fontWeight:900,color:C.blue}}>{preview.iguales.length}</div><div style={{fontSize:9,color:C.textMuted}}>iguales</div></div>
            <div style={{background:C.redDim,border:`1px solid ${C.red}33`,borderRadius:7,padding:"6px 7px"}}><div style={{fontSize:14,fontWeight:900,color:C.red}}>{preview.duplicados.length}</div><div style={{fontSize:9,color:C.textMuted}}>duplic.</div></div>
          </div>
          <Line label="Cambios a enviar" value={fmtNum(cambios)} color={cambios?C.yellow:C.green}/>
        </>
      )}

      {result&&(
        <div style={{marginTop:2,paddingTop:8,borderTop:`1px solid ${C.border}`,display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:6}}>
          <div><div style={{fontSize:13,fontWeight:900,color:C.green}}>{result.added||0}</div><div style={{fontSize:9,color:C.textMuted}}>agreg.</div></div>
          <div><div style={{fontSize:13,fontWeight:900,color:C.yellow}}>{result.updated||0}</div><div style={{fontSize:9,color:C.textMuted}}>actual.</div></div>
          <div><div style={{fontSize:13,fontWeight:900,color:C.blue}}>{result.updateGroups||0}</div><div style={{fontSize:9,color:C.textMuted}}>grupos</div></div>
        </div>
      )}
    </div>
  );
}



function PasteDataBox({targets,onLoadRows,disabled}){
  const[open,setOpen]=useState(false);
  const[selectedId,setSelectedId]=useState("rop05");
  const[text,setText]=useState("");
  const[preview,setPreview]=useState([]);
  const[localError,setLocalError]=useState(null);
  const target=targets.find(t=>t.id===selectedId)||targets[0];
  const handleLoad=()=>{
    setLocalError(null);
    const rows=buildRowsFromPastedTextForTarget(target,text);
    if(!rows.length){setLocalError(`No se detectaron filas válidas para ${target.sourceLabel}. Revisá que hayas copiado el rango completo y en el orden esperado.`);return;}
    setPreview(rows.slice(0,10));
    onLoadRows(target,rows,text.length);
  };
  const handleClear=()=>{setText("");setPreview([]);setLocalError(null);};
  const changeTarget=(id)=>{setSelectedId(id);setPreview([]);setLocalError(null);};
  const previewCols=previewColsForPasteTarget(target);
  return(
    <Card title="Carga por datos">
      <div style={{padding:16,display:"flex",flexDirection:"column",gap:12}}>
        <button onClick={()=>setOpen(o=>!o)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,width:"100%",padding:"10px 12px",borderRadius:9,border:`1px solid ${C.border}`,background:C.surface,color:C.text,cursor:"pointer",fontFamily:"Inter",fontWeight:800}}>
          <span style={{display:"flex",alignItems:"center",gap:8}}><Icon name="parts" size={16} color={C.green}/> Carga por datos — pegar rango desde Excel/Sheets</span>
          <Icon name="chevronDown" size={17} color={C.textMuted} style={{transform:open?"rotate(180deg)":"none",transition:"transform .15s"}}/>
        </button>
        {open&&(
          <div style={{display:"flex",flexDirection:"column",gap:12}}>
            <AlertBanner type="info">Elegí la planilla, copiá el rango desde Excel/Sheets y pegalo acá. Se ignoran los encabezados si vienen incluidos; la carga se interpreta por posición de columna.</AlertBanner>
            <Sel label="Planilla a cargar" value={target.id} onChange={changeTarget} options={targets.map(t=>({value:t.id,label:t.sourceLabel}))}/>
            <div style={{fontSize:11,color:C.textMuted}}>Estructura esperada: <strong style={{color:C.textSub}}>{pasteStructureText(target)}</strong></div>
            <textarea value={text} onChange={e=>setText(e.target.value)} disabled={disabled}
              placeholder={`Pegá acá el rango de ${target.sourceLabel} copiado desde Excel o Google Sheets...`}
              style={{width:"100%",minHeight:160,resize:"vertical",background:C.surface,color:C.text,border:`1px solid ${C.border}`,borderRadius:9,padding:12,fontFamily:"Consolas, monospace",fontSize:12,outline:"none"}}/>
            <div style={{display:"flex",justifyContent:"flex-end",alignItems:"center",gap:8,flexWrap:"wrap"}}>
              <button onClick={handleClear} disabled={disabled||!text} style={{padding:"8px 12px",borderRadius:8,border:`1px solid ${C.border}`,background:C.surface,color:C.textSub,cursor:disabled||!text?"not-allowed":"pointer",fontWeight:700}}>Limpiar</button>
              <button onClick={handleLoad} disabled={disabled||!text.trim()} style={{padding:"8px 14px",borderRadius:8,border:`1px solid ${target.color}55`,background:text.trim()?target.color+"22":C.surface,color:text.trim()?target.color:C.textMuted,cursor:disabled||!text.trim()?"not-allowed":"pointer",fontWeight:900}}>Cargar datos pegados</button>
            </div>
            {localError&&<AlertBanner type="error">{localError}</AlertBanner>}
            {preview.length>0&&(
              <Card title={`Vista previa — ${preview.length} primeras filas de ${target.sourceLabel}`}>
                <Table cols={previewCols} rows={preview} maxH={260} disableTooltip/>
              </Card>
            )}
          </div>
        )}
      </div>
    </Card>
  );
}



function rowHasAnyValue(row){
  if(!row)return false;
  return Object.values(row).some(v=>String(v??"").trim()!=="");
}
function dateForImportTargetRow(target,row){
  if(!row||target?.kind==="insumos")return"";
  if(target?.kind==="rop02"){
    return normDate(row.fecha||row.Fecha||row["Fecha"]||row["Fecha:"]||"");
  }
  if(target?.kind==="rop05"){
    // Para el cartel de Importar datos, ROP05 debe mostrar la FECHA DE CARGA
    // de la última fila real, no la fecha del parte diario usada en controles.
    return normDate(
      row.fechaCarga||
      row.FechaCarga||
      row["FechaCarga"]||
      row["Fecha de carga"]||
      row["FECHA DE CARGA"]||
      row["Marca Temporal"]||
      row["Marca Tmeporal"]||
      row["Timestamp"]||
      row["Marca temporal"]||
      ""
    );
  }
  if(target?.kind==="rma15"){
    return normDate(row.fecha||row["Fecha de OT"]||row["FECHA DE OT"]||row.Fecha||"");
  }
  return normDate(row.fecha||row.Fecha||row.FechaParte||row["Fecha del Parte Diario"]||row["Fecha de OT"]||"");
}
function lastRegisterInfoForTarget(target,currentRows){
  // IMPORTANTE: esto debe mostrar la última fila física con datos de la planilla base,
  // no la última fila "válida" después de normalizar/filtrar.
  // Por eso se usa el último objeto no vacío recibido desde Apps Script y se calcula:
  // fila real = fila de encabezado + posición del registro.
  const rows=Array.isArray(currentRows)?currentRows:[];
  if(!rows.length)return {label:"Último registro: sin datos",date:"",rowNumber:"—",raw:null};

  let bestIdx=-1;
  for(let i=rows.length-1;i>=0;i--){
    if(rowHasAnyValue(rows[i])){bestIdx=i;break;}
  }
  if(bestIdx<0)return {label:"Último registro: sin datos",date:"",rowNumber:"—",raw:null};

  const best=rows[bestIdx]||{};
  let date=dateForImportTargetRow(target,best);
  // Si la última fila física no trae fecha, buscar hacia arriba la última fecha disponible
  // solo para mostrarla, sin cambiar el número de fila física.
  if(!date&&target?.kind!=="insumos"){
    for(let i=bestIdx-1;i>=0;i--){
      date=dateForImportTargetRow(target,rows[i]);
      if(date)break;
    }
  }
  const rowNumber=(target.headerRow||1)+bestIdx+1;
  const dateText=target.kind==="insumos"?"base actual":(date?fmtFecha(date):"sin fecha");
  const dateHint=target.kind==="rop05"?" — Fecha de carga":"";
  return {label:`Último registro: ${dateText}${dateHint} (fila ${rowNumber})`,date,rowNumber,raw:best};
}

function PasteDataBoxInline({targets,onLoadRows,onRemove,loadedFiles,previews,resultByTarget,onSelectPreview,disabled,lastInfoByTarget={},
  totalNuevas,totalActualizadas,totalIguales,totalCambios,
  allLoadedAnalyzed,busy,busyLabel,progress,onAnalyze,onConfirm,onClear,selectedPreview,setSelectedPreview}){

  // Un estado de texto por cada target
  const[texts,setTexts]=useState(()=>Object.fromEntries(targets.map(t=>[t.id,""])));
  const[errors,setErrors]=useState({});
  const loadedFilesList=Object.values(loadedFiles);
  const hasData=loadedFilesList.length>0;

  const handleLoad=(target)=>{
    const text=texts[target.id]||"";
    setErrors(e=>({...e,[target.id]:null}));
    const rows=buildRowsFromPastedTextForTarget(target,text);
    if(!rows.length){setErrors(e=>({...e,[target.id]:"No se detectaron filas válidas. Revisá el orden de columnas."}));return;}
    onLoadRows(target,rows,text.length);
    setTexts(t=>({...t,[target.id]:""}));
  };

  return(
    <div style={{display:"flex",flexDirection:"column",gap:14}}>
      <Card title="Importar datos a planillas base">
        <div style={{padding:16,display:"flex",flexDirection:"column",gap:10}}>

          {/* Fila de cada planilla */}
          {targets.map(t=>{
            const text=texts[t.id]||"";
            const loaded=loadedFiles[t.id];
            const preview=previews[t.id];
            const cambios=preview?(preview.nuevos.length+preview.actualizados.length):0;
            return(
              <div key={t.id} style={{display:"grid",gridTemplateColumns:"200px 1fr auto",gap:10,alignItems:"start",padding:"12px",borderRadius:10,border:`1px solid ${t.color}44`,background:loaded?t.color+"18":t.color+"08"}}>
                {/* Columna izquierda: nombre + estado */}
                <div style={{display:"flex",flexDirection:"column",gap:6,paddingTop:4,borderRight:`2px solid ${t.color}33`,paddingRight:10}}>
                  <div style={{display:"flex",alignItems:"center",gap:6}}>
                    <div style={{width:8,height:8,borderRadius:"50%",background:t.color,flexShrink:0}}/>
                    <span style={{fontSize:13,fontWeight:800,color:t.color}}>{t.sourceLabel}</span>
                  </div>
                  <span style={{fontSize:10,color:C.textMuted,lineHeight:1.4}}>{pasteStructureText(t).slice(0,80)}…</span>
                  <div style={{marginTop:4,padding:"5px 7px",borderRadius:7,background:C.card,border:`1px solid ${t.color}33`,color:t.color,fontSize:11,fontWeight:900,lineHeight:1.25}}>
                    {lastInfoByTarget[t.id]?.label||"Último registro: sin datos"}
                  </div>
                  {loaded&&(
                    <div style={{display:"flex",flexDirection:"column",gap:4,marginTop:4}}>
                      {preview
                        ? <Badge color={cambios>0?C.yellow:C.green}>{cambios>0?`${cambios} cambios`:"Sin cambios"}</Badge>
                        : <Badge color={C.textMuted}>Sin analizar</Badge>
                      }
                      <button onClick={()=>onRemove(t.id)}
                        style={{background:"none",border:`1px solid ${C.border}`,borderRadius:6,color:C.textMuted,cursor:"pointer",padding:"3px 8px",fontSize:11,width:"fit-content"}}>
                        Quitar
                      </button>
                    </div>
                  )}
                </div>
                {/* Columna central: textarea */}
                <textarea
                  value={text}
                  onChange={e=>setTexts(tx=>({...tx,[t.id]:e.target.value}))}
                  disabled={disabled||!!loaded}
                  placeholder={loaded?"✓ Datos cargados — quitalos para cargar nuevos":`Pegá acá el rango de ${t.sourceLabel}...`}
                  style={{width:"100%",height:90,resize:"vertical",background:loaded?C.card:C.surface,color:loaded?C.textMuted:C.text,border:`1px solid ${errors[t.id]?C.red:t.color+"44"}`,borderRadius:8,padding:10,fontFamily:"Consolas,monospace",fontSize:11,outline:"none",opacity:loaded?0.6:1}}/>
                {/* Columna derecha: botón */}
                <div style={{display:"flex",flexDirection:"column",gap:6,paddingTop:4}}>
                  <button onClick={()=>handleLoad(t)} disabled={disabled||!text.trim()||!!loaded}
                    style={{padding:"9px 14px",borderRadius:8,border:`1px solid ${t.color}55`,background:text.trim()&&!loaded?t.color+"22":C.surface,color:text.trim()&&!loaded?t.color:C.textMuted,cursor:disabled||!text.trim()||loaded?"not-allowed":"pointer",fontWeight:900,fontSize:12,whiteSpace:"nowrap"}}>
                    Cargar
                  </button>
                  {text&&!loaded&&(
                    <button onClick={()=>setTexts(tx=>({...tx,[t.id]:""}))}
                      style={{padding:"6px 10px",borderRadius:8,border:`1px solid ${C.border}`,background:C.surface,color:C.textMuted,cursor:"pointer",fontWeight:700,fontSize:11}}>
                      Limpiar
                    </button>
                  )}
                </div>
                {errors[t.id]&&<div style={{gridColumn:"1/-1",fontSize:11,color:C.red}}>{errors[t.id]}</div>}
              </div>
            );
          })}

          {/* Barra de acción — solo si hay datos cargados */}
          {hasData&&(
            <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",paddingTop:10,borderTop:`2px solid ${C.accent}33`,marginTop:4,background:C.accentDim,borderRadius:10,padding:12}}>
              <div style={{display:"flex",gap:8,flex:1,flexWrap:"wrap"}}>
                <StatCard icon="check" label="Nuevas" value={totalNuevas} color={C.green} small/>
                <StatCard icon="refresh" label="Actualizadas" value={totalActualizadas} color={C.yellow} small/>
                <StatCard icon="consist" label="Sin cambios" value={totalIguales} color={C.blue} small/>
              </div>
              <div style={{display:"flex",gap:8,flexShrink:0}}>
                <button onClick={onClear} disabled={busy}
                  style={{padding:"9px 14px",borderRadius:8,border:`1px solid ${C.border}`,background:C.surface,color:C.textSub,cursor:busy?"not-allowed":"pointer",fontWeight:600}}>
                  Limpiar todo
                </button>
                <button disabled={busy||!hasData} onClick={onAnalyze}
                  style={{padding:"9px 16px",borderRadius:8,border:`1px solid ${C.yellow}55`,background:hasData?C.yellowDim:C.surface,color:hasData?C.yellow:C.textMuted,cursor:hasData&&!busy?"pointer":"not-allowed",fontWeight:800}}>
                  Analizar cambios
                </button>
                <button disabled={busy||!allLoadedAnalyzed||totalCambios===0} onClick={onConfirm}
                  style={{padding:"9px 16px",borderRadius:8,border:`1px solid ${C.green}55`,background:(allLoadedAnalyzed&&totalCambios)?C.greenDim:C.surface,color:(allLoadedAnalyzed&&totalCambios)?C.green:C.textMuted,cursor:(allLoadedAnalyzed&&totalCambios&&!busy)?"pointer":"not-allowed",fontWeight:800}}>
                  Actualizar Google Sheets
                </button>
              </div>
            </div>
          )}

          {busy&&progress.total>0&&(
            <div style={{display:"flex",flexDirection:"column",gap:6}}>
              <div style={{display:"flex",justifyContent:"space-between",fontSize:11,color:C.textSub,fontWeight:700}}><span>{busyLabel}</span><span>{progress.done}/{progress.total}</span></div>
              <div style={{height:7,background:C.border,borderRadius:999,overflow:"hidden"}}><div style={{height:"100%",width:`${Math.round((progress.done/progress.total)*100)}%`,background:C.accent,borderRadius:999,transition:"width .2s"}}/></div>
            </div>
          )}
        </div>
      </Card>
    </div>
  );
}

function ViewImportExcel({rop02All,rop05,rma15,insumos,rawSources,onReload}){
  const[busy,setBusy]=useState(false);
  const[busyLabel,setBusyLabel]=useState("");
  const[progress,setProgress]=useState({done:0,total:0});
  const[files,setFiles]=useState({});
  const[previews,setPreviews]=useState({});
  const[selectedPreview,setSelectedPreview]=useState(null);
  const[message,setMessage]=useState(null);
  const[error,setError]=useState(null);
  const[results,setResults]=useState([]);
  const targets=Object.values(IMPORT_TARGETS);

  const currentForTarget=(target)=>{
    if(target.kind==="rop02")return (rop02All||[]).filter(r=>!target.proyecto||normProject(r.proyecto)===target.proyecto);
    if(target.kind==="rop05")return rop05;
    if(target.kind==="rma15")return (rma15||[]).filter(r=>!target.proyecto||normProject(r.proyecto)===target.proyecto);
    if(target.kind==="insumos")return Object.entries(insumos||{}).map(([codigo,info])=>({codigo,descripcion:info.descripcion||"",costoUnitario:info.costoUnitario||0}));
    return [];
  };

  const rawForTarget=(target)=>{
    const data=rawSources?.[target.id]?.ok&&Array.isArray(rawSources[target.id].data)?rawSources[target.id].data:null;
    return data||currentForTarget(target);
  };

  const lastInfoByTarget=useMemo(()=>{
    const map={};
    targets.forEach(t=>{map[t.id]=lastRegisterInfoForTarget(t,rawForTarget(t));});
    return map;
  },[rawSources,rop02All,rop05,rma15,insumos]);

  const loadPastedRows=(target,rows,size=0)=>{
    setError(null);setMessage(null);setResults([]);
    setFiles(p=>({...p,[target.id]:{target,pastedRows:rows,fileName:`Datos pegados ${target.sourceLabel}`,size,loadedAt:new Date().toISOString(),isPasted:true}}));
    setPreviews(p=>{const n={...p};delete n[target.id];return n;});
    setSelectedPreview(p=>p?.target?.id===target.id?null:p);
  };

  const removeFile=(targetId)=>{
    setFiles(p=>{const n={...p};delete n[targetId];return n;});
    setPreviews(p=>{const n={...p};delete n[targetId];return n;});
    setSelectedPreview(p=>p?.target?.id===targetId?null:p);
  };

  const analyzeAll=async()=>{
    const entries=Object.values(files);
    if(!entries.length){setMessage("Primero pegá datos en al menos una planilla.");return;}
    setBusy(true);setBusyLabel("Analizando datos...");setProgress({done:0,total:entries.length});setError(null);setMessage(null);setResults([]);
    try{
      const built=[];
      const needsFreshRop05=entries.some(entry=>entry.target?.kind==="rop05");
      let freshRop05Rows=rop05;
      if(needsFreshRop05){
        try{
          setBusyLabel("Leyendo ROP05 completo desde Google Sheets...");
          const src=await fetchSource(APPS_SCRIPT_URL,"rop05",{force:true});
          if(src?.ok&&Array.isArray(src.data))freshRop05Rows=normalizeROP05(src.data);
        }catch(err){console.warn("No se pudo refrescar ROP05",err);}
        setBusyLabel("Analizando datos...");
      }
      const currentRowsForPreview=(target)=>target.kind==="rop05"?freshRop05Rows:currentForTarget(target);
      await Promise.all(entries.map(async(entry)=>{
        const target=entry.target;
        const parsed={sheetName:"Pegado manual",headers:["FechaCarga","CorreoSupervisor","Proyecto","GrupoTrabajo","Equipo","NroParte","TipoEquipo","FechaParte","Tarea","HorasProductivas","CantidadProduccion","Unidad","Observacion"],rows:entry.pastedRows};
        const normalized=normalizeImportedRows(target,parsed.rows,insumos);
        const prev=buildImportPreview(target,parsed.rows,normalized,currentRowsForPreview(target));
        const full={target,fileName:entry.fileName,sheetName:parsed.sheetName,headers:parsed.headers,...prev,parsedAt:new Date().toISOString()};
        built.push(full);
        setProgress(p=>({done:p.done+1,total:p.total}));
      }));
      const map={};built.forEach(p=>{map[p.target.id]=p;});
      setPreviews(map);
      setSelectedPreview(built[0]||null);
      const nuevas=built.reduce((s,p)=>s+p.nuevos.length,0);
      const actualizadas=built.reduce((s,p)=>s+p.actualizados.length,0);
      setMessage(`Análisis completo: ${nuevas} nuevas y ${actualizadas} actualizadas detectadas.`);
    }catch(err){setError(err.message);}
    finally{setBusy(false);setBusyLabel("");setProgress({done:0,total:0});}
  };

  const loadedFiles=Object.values(files);
  const loadedPreviews=Object.values(previews);
  const allLoadedAnalyzed=loadedFiles.length>0&&loadedFiles.every(f=>!!previews[f.target.id]);
  const pendingAnalyze=loadedFiles.filter(f=>!previews[f.target.id]).length;
  const totalNuevas=loadedPreviews.reduce((s,p)=>s+p.nuevos.length,0);
  const totalActualizadas=loadedPreviews.reduce((s,p)=>s+p.actualizados.length,0);
  const totalIguales=loadedPreviews.reduce((s,p)=>s+p.iguales.length,0);
  const totalDuplicadas=loadedPreviews.reduce((s,p)=>s+p.duplicados.length,0);
  const totalCambios=totalNuevas+totalActualizadas;
  const resultByTarget=useMemo(()=>{const map={};(results||[]).forEach(r=>{if(r?.target?.id)map[r.target.id]=r;});return map;},[results]);

  const confirmAll=async()=>{
    if(!allLoadedAnalyzed){setMessage("Primero tocá Analizar cambios.");return;}
    const toRun=Object.values(previews).filter(p=>(p.nuevos.length+p.actualizados.length)>0);
    if(!toRun.length){setMessage("No hay filas nuevas ni modificadas para actualizar.");return;}
    setBusy(true);setBusyLabel("Actualizando Google Sheets...");setProgress({done:0,total:toRun.length});setError(null);setMessage(null);setResults([]);
    try{
      const allResults=[];
      for(const prev of toRun){
        const result=await postImportUpsert(prev);
        allResults.push({target:prev.target,...result});
        setProgress(p=>({done:p.done+1,total:p.total}));
      }
      setResults(allResults);
      const added=allResults.reduce((s,r)=>s+(r.added||0),0);
      const updated=allResults.reduce((s,r)=>s+(r.updated||0),0);
      const unchanged=allResults.reduce((s,r)=>s+(r.unchanged||0),0);
      const groups=allResults.reduce((s,r)=>s+(r.updateGroups||0),0);
      setMessage(`Actualización completa: ${added} agregadas, ${updated} actualizadas, ${unchanged} sin cambios. Grupos: ${groups}.`);
      setFiles({});setPreviews({});setSelectedPreview(null);
      if(onReload)await onReload();
    }catch(err){setError(err.message);}
    finally{setBusy(false);setBusyLabel("");setProgress({done:0,total:0});}
  };

  const clearAll=()=>{setFiles({});setPreviews({});setSelectedPreview(null);setResults([]);setMessage(null);setError(null);setProgress({done:0,total:0});};

  const detail=selectedPreview;
  const sampleRows=detail?[...detail.nuevos.map(r=>({...r,_tipoImport:"Nueva"})),...detail.actualizados.map(r=>({...r,_tipoImport:"Actualiza"}))].slice(0,120):[];
  const cols=[
    {key:"_tipoImport",label:"Acción",render:v=><Badge color={v==="Nueva"?C.green:C.yellow}>{v}</Badge>},
    {key:"fecha",label:"Fecha",render:v=>fmtFecha(v)},
    {key:"proyecto",label:"Proyecto",render:v=><Badge color={proyColor(v)}>{v}</Badge>},
    {key:"maquina",label:"Máquina",render:v=><Badge color={C.purple}>{v}</Badge>},
    {key:"parte",label:"Parte"},
    {key:"tarea",label:"Tarea",wrap:true},
    {key:"horas",label:"Hs",render:v=>fmtNum(v)},
    {key:"cantidad",label:"Cantidad",render:v=>fmtNum(v)},
    {key:"codigo",label:"Código"},
    {key:"descripcion",label:"Descripción",wrap:true},
    {key:"costoUnitario",label:"Costo unit.",render:v=>v?"$"+fmtNum(v):"—"},
  ];

  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:14}}>
      <PasteDataBoxInline
        targets={targets}
        onLoadRows={loadPastedRows}
        onRemove={removeFile}
        loadedFiles={files}
        previews={previews}
        resultByTarget={resultByTarget}
        onSelectPreview={setSelectedPreview}
        disabled={busy}
        lastInfoByTarget={lastInfoByTarget}
        // action bar props
        pendingAnalyze={pendingAnalyze}
        totalNuevas={totalNuevas}
        totalActualizadas={totalActualizadas}
        totalIguales={totalIguales}
        totalDuplicadas={totalDuplicadas}
        totalCambios={totalCambios}
        allLoadedAnalyzed={allLoadedAnalyzed}
        busy={busy}
        busyLabel={busyLabel}
        progress={progress}
        onAnalyze={analyzeAll}
        onConfirm={confirmAll}
        onClear={clearAll}
        loadedPreviews={loadedPreviews}
        selectedPreview={selectedPreview}
        setSelectedPreview={setSelectedPreview}
      />

      {busy&&<AlertBanner type="info">{busyLabel||"Procesando..."}</AlertBanner>}
      {error&&<AlertBanner type="error">{error}</AlertBanner>}
      {message&&<AlertBanner type="success">{message}</AlertBanner>}

      {results.length>0&&(
        <Card title="Resultado de actualización">
          <div style={{padding:16,display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))",gap:10}}>
            {results.map(r=>(
              <div key={r.target.id} style={{background:C.surface,border:`1px solid ${r.target.color}44`,borderRadius:10,padding:12}}>
                <div style={{fontSize:12,fontWeight:800,color:r.target.color,marginBottom:8}}>{r.target.sourceLabel}</div>
                <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:6}}>
                  <div><div style={{fontSize:18,fontWeight:800,color:C.green}}>{r.added||0}</div><div style={{fontSize:10,color:C.textMuted}}>agregadas</div></div>
                  <div><div style={{fontSize:18,fontWeight:800,color:C.yellow}}>{r.updated||0}</div><div style={{fontSize:10,color:C.textMuted}}>actualiz.</div></div>
                  <div><div style={{fontSize:18,fontWeight:800,color:C.blue}}>{r.updateGroups??0}</div><div style={{fontSize:10,color:C.textMuted}}>grupos</div></div>
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      {detail&&(
        <Card title={`Vista previa — ${detail.target.sourceLabel}`} action={<button onClick={()=>setSelectedPreview(null)} style={{background:"none",border:`1px solid ${C.border}`,borderRadius:7,color:C.textSub,padding:"5px 10px",cursor:"pointer",fontSize:11}}>Cerrar</button>}>
          <div style={{padding:16,display:"flex",flexDirection:"column",gap:14}}>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:10}}>
              <StatCard icon="check" label="Nuevas" value={detail.nuevos.length} color={C.green} small/>
              <StatCard icon="refresh" label="Actualizadas" value={detail.actualizados.length} color={C.yellow} small/>
              <StatCard icon="consist" label="Sin cambios" value={detail.iguales.length} color={C.blue} small/>
              <StatCard icon="warn" label="Duplicadas" value={detail.duplicados.length} color={C.red} small/>
            </div>
            {sampleRows.length>0?<Table cols={cols} rows={sampleRows} maxH={360} emptyMsg="No hay cambios para mostrar"/>:<AlertBanner type="success">No hay filas nuevas ni modificadas para esta fuente.</AlertBanner>}
          </div>
        </Card>
      )}
    </div>
  );
}



function HealthDashboard({health,onLoadAll,loading}){
  const rows=Object.entries(health?.sources||{}).map(([key,v])=>({
    key,
    fuente:v.label||key,
    filas:v.rows??"—",
    estado:v.ok?"OK":"Error",
    latencia:v.latency?`${v.latency} ms`:"—",
  }));
  const total=rows.reduce((sum,r)=>sum+(typeof r.filas==="number"?r.filas:0),0);
  return(
    <div className="fade-in" style={{display:"flex",flexDirection:"column",gap:16}}>
      <AlertBanner type="info">Inicio rápido activo: la app abrió solo con diagnóstico. Los datos pesados se cargan recién cuando entrás a cada pestaña.</AlertBanner>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:12}}>
        <StatCard icon="check" label="Fuentes OK" value={rows.filter(r=>r.estado==="OK").length} color={C.green}/>
        <StatCard icon="parts" label="Filas detectadas" value={fmtNum(total)} color={C.blue}/>
        <StatCard icon="refresh" label="Modo" value="Lazy" sub="Carga por pestaña" color={C.accent}/>
      </div>
      <Card title="Estado de fuentes" action={<button onClick={onLoadAll} disabled={loading} style={{background:C.accent,border:"none",borderRadius:7,color:"#fff",padding:"7px 12px",fontSize:12,fontWeight:700,cursor:loading?"not-allowed":"pointer"}}>{loading?"Cargando...":"Cargar dashboard completo"}</button>}>
        <Table cols={[
          {key:"fuente",label:"Fuente"},
          {key:"filas",label:"Filas"},
          {key:"estado",label:"Estado",render:v=><Badge color={v==="OK"?C.green:C.red}>{v}</Badge>},
          {key:"latencia",label:"Lectura"},
        ]} rows={rows} maxH={360} emptyMsg="Sin diagnóstico todavía"/>
      </Card>
    </div>
  );
}

// ─── ViewCostosMant ──────────────────────────────────────────────────────────

function tipoEquipoCosto(maquina){
  const tipo=String(getMachineType(maquina)||"").toUpperCase();
  const code=String(maquina||"").toUpperCase();

  if(tipo.includes("CAMIONETA")||/^CTA/.test(code)||/^AG[0-9]/.test(code)||/^AH[0-9]/.test(code))return "CAMIONETAS";
  if(tipo.includes("CAMION")||/^CAR/.test(code)||/^CAV/.test(code)||/^CAA/.test(code)||/^CAT-[0-9]/.test(code))return "CAMIONES";

  // IMPORTANTE: MINICARGADORA va antes que CARGADORA FRONTAL.
  // Si se evalúa "CARGADORA" primero, MCA-0005 cae mal como cargadora frontal.
  if(tipo.includes("MINICARGADORA"))return "MINICARGADORA";

  if(tipo.includes("EXCAVADORA"))return "EXCAVADORA";
  if(tipo.includes("CARGADORA FRONTAL"))return "CARGADORA FRONTAL";
  if(tipo.includes("MOTONIVELADORA"))return "MOTONIVELADORA";
  if(tipo.includes("TOPADORA"))return "TOPADORA";
  if(tipo.includes("RETROPALA"))return "RETROPALA";
  if(tipo.includes("VIBROCOMPACTADOR"))return "VIBROCOMPACTADOR";
  return "OTROS";
}
function esMaquinaCosto(tipo){
  return ["EXCAVADORA","CARGADORA FRONTAL","MOTONIVELADORA","TOPADORA","RETROPALA","VIBROCOMPACTADOR","MINICARGADORA"].includes(String(tipo||"").toUpperCase());
}

const MESES_ES=["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];
function monthKeyCosto(fecha){
  const f=String(fecha||"").slice(0,10);
  if(!/^\d{4}-\d{2}-\d{2}$/.test(f))return "";
  return f.slice(0,7);
}
function monthLabelCosto(key){
  const m=Number(String(key||"").slice(5,7));
  return MESES_ES[m-1]||key;
}
function addMonthCosto(key){
  const y=Number(key.slice(0,4));
  const m=Number(key.slice(5,7));
  const d=new Date(y,m,1);
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
}
function buildMonthKeysCosto(rows,modoFecha,fechaDia,fechaD,fechaH){
  let minKey="",maxKey="";

  if(modoFecha==="dia"&&fechaDia){
    minKey=maxKey=monthKeyCosto(fechaDia);
  }else if(modoFecha==="periodo"&&(fechaD||fechaH)){
    const keys=(rows||[]).map(r=>monthKeyCosto(r.fecha)).filter(Boolean).sort();
    minKey=fechaD?monthKeyCosto(fechaD):(keys[0]||"");
    maxKey=fechaH?monthKeyCosto(fechaH):(keys[keys.length-1]||"");
  }else{
    const keys=[...new Set((rows||[]).map(r=>monthKeyCosto(r.fecha)).filter(Boolean))].sort();
    return keys.map(k=>({key:k,label:monthLabelCosto(k)}));
  }

  if(!minKey||!maxKey)return [];
  const out=[];
  for(let k=minKey;k<=maxKey;k=addMonthCosto(k)){
    out.push({key:k,label:monthLabelCosto(k)});
    if(out.length>36)break;
  }
  return out;
}

